<?php require dirname(__DIR__).'/config.php';admin_required();$pdo=db();verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$keys=['store_name','delivery_fee','free_delivery_minimum','support_phone'];foreach($keys as $k){$v=trim($_POST[$k]??'');$s=$pdo->prepare("INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)");$s->execute([$k,$v]);}flash('Store settings saved. Note: delivery fee display/checkout uses the configured code defaults until wired into checkout logic.');header('Location: settings.php');exit;}$all=$pdo->query("SELECT setting_key,setting_value FROM settings")->fetchAll(PDO::FETCH_KEY_PAIR);?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Settings — Aastha Admin</title><link rel="stylesheet" href="../assets/css/admin.css"></head><body><div class="admin-shell"><aside class="sidebar"><a class="admin-brand" href="index.php"><span>A</span><b>Aastha<small>ADMIN PANEL</small></b></a><div class="side-label">MAIN MENU</div><a class="side-link" href="index.php"><i>▦</i> Dashboard</a><a class="side-link" href="orders.php"><i>☷</i> Orders</a><a class="side-link" href="products.php"><i>▣</i> Products</a><a class="side-link" href="categories.php"><i>▤</i> Categories</a><a class="side-link" href="customers.php"><i>♙</i> Customers</a><a class="side-link active" href="settings.php"><i>⚙</i> Store settings</a><div class="side-bottom"><a class="side-link" href="../index.php"><i>↗</i> View storefront</a><a class="side-link" href="logout.php"><i>⇥</i> Logout</a></div></aside><main class="admin-main"><header class="admin-topbar"><button class="mobile-menu" data-menu>☰</button><div class="crumb">Home <span>›</span> Store settings</div><div class="admin-user"><span class="avatar">A</span><?=e($_SESSION['admin_name']??'Admin')?> <a href="logout.php">Logout ↗</a></div></header><section class="admin-content"><div class="page-title-row"><div><h1>Store settings</h1><p>Basic settings for your Aastha storefront</p></div></div><?php show_flash(); ?><form class="panel edit-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="panel-head"><h2>Store information</h2></div><div class="form-grid"><label>Store name<input name="store_name" value="<?=e($all['store_name']??'Aastha')?>" required></label><label>Support phone<input name="support_phone" value="<?=e($all['support_phone']??'')?>"></label><label>Local delivery fee (৳)<input type="number" min="0" step=".01" name="delivery_fee" value="<?=e($all['delivery_fee']??'60')?>"></label><label>Free delivery minimum (৳)<input type="number" min="0" step=".01" name="free_delivery_minimum" value="<?=e($all['free_delivery_minimum']??'1000')?>"></label></div><div class="settings-note"><b>Payment method</b><p>Cash on delivery is enabled. No online payment gateway is configured.</p><b>Security</b><p>Use HTTPS, strong admin passwords, and delete setup-admin.php after creating the first admin account.</p></div><button class="btn primary">Save settings</button></form></section></main></div><script src="../assets/js/admin.js"></script></body></html>